#include <iostream>
using namespace std;

int gcd(int a, int b)
{
    if (b == 0) return a;
    return gcd(b, a%b);
}

int main()
{
    int a, b, x, y;
    cin >> a >> b >> x >> y;

    int d = gcd(x, y);
    x /= d; y /= d;
    int k1 = a / x;
    int k2 = b / y;
    int k = min(k1, k2);

    cout << x * k << " " << y * k << endl;
}
